const email=clean(b.email,160)?.toLowerCase()||null;
if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('E-mail inválido');
const company=clean(b.company,120), produto=clean(b.product,120), summary=clean(b.summary,1200);
