const identity_url='https://udcsokdtdqqdnoqozbxh.supabase.co/rest/v1/contacts?select=id,name,email,phone,whatsapp,company,status,produto,priority&user_id=eq.0af00833-c1f7-42f4-9543-a5e0ff6f55fc&or=(whatsapp.eq.'+encodeURIComponent(whatsapp)+',phone.eq.'+encodeURIComponent(phone)+',phone.eq.'+encodeURIComponent(whatsapp)+')';
