const b=$json.body??$json; const p=b.payment??{};
if(!['PAYMENT_CONFIRMED','PAYMENT_RECEIVED','PAYMENT_REFUNDED','PAYMENT_PARTIALLY_REFUNDED'].includes(b.event)) return [];
if(!p.id) throw new Error('Asaas sem payment id');
